#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<long long> c(2 * n + 1, 0);
    c[n] = 1;
    for (int i = n - 1; i >= 1; --i) {
        c[i] = (2 * c[i + 1]) % m;
        for (int j = 2; j <= n / i; ++j) {
            c[i] = (c[i] + c[i * j] - c[(i + 1) * j]) % m;
        }
        // Ensure c[i] is non-negative
        c[i] = (c[i] + m) % m;
    }
    cout << (c[1] - c[2] + m) % m << endl;
    return 0;
}
